31	func (p *StdinPrompter) Prompt(f FieldSpec) (any, error) {
32		if len(f.Enum) > 0 {
33			return p.promptEnum(f)
34		}
35		return p.promptScalar(f)
36	}
37	
38	func (p *StdinPrompter) promptScalar(f FieldSpec) (any, error) {
39		var re *regexp.Regexp
40		if f.Pattern != "" {
41			var err error
42			re, err = regexp.Compile(f.Pattern)
43			if err != nil {
44				return nil, fmt.Errorf("invalid pattern for %q: %w", f.Name, err)
45			}
46		}
47		for {
48			p.writeLabel(f)
49			raw, ok, err := p.readLine()
50			if err != nil {
51				return nil, err
52			}
53			if !ok {
54				return nil, io.EOF
55			}
56			if raw == "" {
57				return f.Default, nil
58			}
59			v := coerce(raw, f.Type)
60			if isTypedField(f.Type) {
61				if _, stillStr := v.(string); stillStr {
62					fmt.Fprintf(p.out, "  ! %q is not a valid %s\n", raw, f.Type)
63					continue
64				}
65			}
66			if re != nil {
67				s, ok := v.(string)
68				if !ok || !re.MatchString(s) {
69					fmt.Fprintf(p.out, "  ! value must match %s\n", f.Pattern)
70					continue
71				}
72			}
73			return v, nil
74		}
75	}
